<div class="matrix-container">
<h2 style="color: #2c3e50;">Calculadora de Matrices</h2>
<div class="matrix-wrapper">
<div class="matrix-box">
<h3>Matriz A</h3>
<form id="mA">
<div class="matrix-grid"><input type="text" name="a11" value="0" /> <input type="text" name="a12" value="0" /> <input type="text" name="a13" value="0" /> <input type="text" name="a21" value="0" /> <input type="text" name="a22" value="0" /> <input type="text" name="a23" value="0" /> <input type="text" name="a31" value="0" /> <input type="text" name="a32" value="0" /> <input type="text" name="a33" value="0" /></div>
<br /><br /><input type="reset" value="Limpiar A" class="btn btn-clear" /></form></div>
<div class="matrix-box">
<h3>Matriz B</h3>
<form id="mB">
<div class="matrix-grid"><input type="text" name="a11" value="0" /> <input type="text" name="a12" value="0" /> <input type="text" name="a13" value="0" /> <input type="text" name="a21" value="0" /> <input type="text" name="a22" value="0" /> <input type="text" name="a23" value="0" /> <input type="text" name="a31" value="0" /> <input type="text" name="a32" value="0" /> <input type="text" name="a33" value="0" /></div>
<br /><br /><input type="reset" value="Limpiar B" class="btn btn-clear" /></form></div>
<div class="matrix-box">
<h3>Matriz C</h3>
<form id="mC">
<div class="matrix-grid"><input type="text" name="a11" readonly="readonly" style="background: #f0f0f0;" /> <input type="text" name="a12" readonly="readonly" style="background: #f0f0f0;" /> <input type="text" name="a13" readonly="readonly" style="background: #f0f0f0;" /> <input type="text" name="a21" readonly="readonly" style="background: #f0f0f0;" /> <input type="text" name="a22" readonly="readonly" style="background: #f0f0f0;" /> <input type="text" name="a23" readonly="readonly" style="background: #f0f0f0;" /> <input type="text" name="a31" readonly="readonly" style="background: #f0f0f0;" /> <input type="text" name="a32" readonly="readonly" style="background: #f0f0f0;" /> <input type="text" name="a33" readonly="readonly" style="background: #f0f0f0;" /></div>
<br /><br /><input type="reset" value="Limpiar C" class="btn btn-clear" /></form></div>
</div>
<div class="controls"><input type="button" value="Sumar (A + B = C)" class="btn" onclick="operate('add')" /> <input type="button" value="Restar (A - B = C)" class="btn" onclick="operate('rest')" /></div>
</div>
<p>
<script>
function operate(type) {
    const fA = document.getElementById('mA');
    const fB = document.getElementById('mB');
    const fC = document.getElementById('mC');

    for (let i = 1; i <= 3; i++) {
        for (let j = 1; j <= 3; j++) {
            let field = "a" + i + j;
            let valA = parseFloat(fA[field].value) || 0;
            let valB = parseFloat(fB[field].value) || 0;

            if (type === 'add') {
                fC[field].value = (valA + valB).toFixed(2).replace(/\.00$/, '');
            } else {
                fC[field].value = (valA - valB).toFixed(2).replace(/\.00$/, '');
            }
        }
    }
}
</script>
</p>","textFeedbackInput":"Mostrar retroalimentación","textFeedbackTextarea":""}

